    u8 state = (++sprite->sTimer / 2) % 4;

    if (sprite->sTimer >= 3)
    {
        switch (state)
        {
        default:
            x = 1;
            break;
        case 1:
        case 2:
            x = -1;
            break;
        }

        sprite->x += x;
        if (++sprite->sTimer >= 40)
        {
            sprite->sState = 0;
            sprite->x = GetDodrioXPos(0, GetNumPlayers());
        }
    }

    return 0;

