        LoadSpriteSheet(&sheet);
        LoadSpritePalette(&pal);
        for (i = 0; i < NUM_CLOUDS; i++)
        {
            sCloudSpriteIds[i] = AllocZeroed(4);
            *sCloudSpriteIds[i] = CreateSprite(&template, sCloudStartCoords[i][0], sCloudStartCoords[i][1], 4);
        }
    }

    Free(ptr);

