        if (!IsDma3ManagerBusyWithBgCopy())
        {
            PutWindowTilemap(sGfx->windowIds[WIN_PLAY_AGAIN]);
            PutWindowTilemap(sGfx->windowIds[WIN_YES_NO]);
        }
        CopyBgTilemapBufferToVram(BG_INTERFACE);
        sGfx->state++;
        break;
